const BG_PRESETS = { white: '#f8f8f9', cool: '#eef2f7' };
const hexRgb = (h) => { const n = parseInt(String(h).slice(1), 16); return [n >> 16, (n >> 8) & 255, n & 255]; };
const mixRgb = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
const rgbHex = (c) => '#' + c.map((v) => v.toString(16).padStart(2, '0')).join('');
const rgba = (c, a) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
function brandCss(brand, accent, bg) {
  const light = []; const dark = [];
  if (/^#[0-9a-f]{6}$/i.test(brand)) {
    const b = hexRgb(brand); const dk = mixRgb(b, [255, 255, 255], 0.3);
    light.push(`--brand:${brand}`, `--brand-d:${rgbHex(mixRgb(b, [0, 0, 0], 0.25))}`, `--brand-l:${rgba(b, 0.09)}`, `--blob1:${rgba(b, 0.2)}`, `--blob3:${rgba(b, 0.1)}`);
    dark.push(`--brand:${rgbHex(dk)}`, `--brand-d:${rgbHex(mixRgb(b, [255, 255, 255], 0.12))}`, `--brand-l:${rgba(dk, 0.14)}`, `--blob1:${rgba(b, 0.35)}`, `--blob3:${rgba(b, 0.3)}`);
  }
  if (/^#[0-9a-f]{6}$/i.test(accent)) {
    const a = hexRgb(accent);
    light.push(`--gold:${accent}`, `--blob2:${rgba(a, 0.22)}`);
    dark.push(`--gold:${rgbHex(mixRgb(a, [255, 255, 255], 0.15))}`, `--blob2:${rgba(a, 0.2)}`);
  }
  if (BG_PRESETS[bg]) light.push(`--bg:${BG_PRESETS[bg]}`);
  if (!light.length) return '';
  const d = dark.join(';');
  return `:root{${light.join(';')}}@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){${d}}}:root[data-theme="dark"]{${d}}`;
}
const slugify = (s) => String(s || '').toLowerCase().trim().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '').slice(0, 60);
