const attr = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const cut = (s, n) => { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// نص بسيط → HTML: «## عنوان» و«- نقطة» وسطر عادي = فقرة
function richHtml(text, store = '') {
  let out = ''; let list = [];
  const flush = () => { if (list.length) { out += `<ul>${list.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>`; list = []; } };
  for (const raw of String(text || '').replace(/\{store\}/g, store).split(/\n+/)) {
    const l = raw.trim(); if (!l) continue;
    if (/^[-•*]\s+/.test(l)) list.push(l.replace(/^[-•*]\s+/, ''));
    else if (/^##\s+/.test(l)) { flush(); out += `<h3>${esc(l.replace(/^##\s+/, ''))}</h3>`; }
    else { flush(); out += `<p>${esc(l)}</p>`; }
  }
  flush(); return out;
}
