// يحقن وسوم SEO والمحتوى المسبق في قالب index.html (يستفيد منه زواحف جوجل والمشاركة على السوشيال)
function renderIndex(tpl, s) {
  const j = (o) => JSON.stringify(o).replace(/</g, '\\u003c');
  let head = `<title>${esc(s.title)}</title>\n<meta name="description" content="${attr(s.desc)}">\n<link rel="canonical" href="${attr(s.canonical)}">\n<meta name="robots" content="${s.robots}">\n`;
  if (s.keywords) head += `<meta name="keywords" content="${attr(s.keywords)}">\n`;
  head += `<meta property="og:type" content="${s.ogType || 'website'}">\n<meta property="og:site_name" content="${attr(s.siteName)}">\n<meta property="og:locale" content="ar_AR">\n<meta property="og:title" content="${attr(s.title)}">\n<meta property="og:description" content="${attr(s.desc)}">\n<meta property="og:url" content="${attr(s.canonical)}">\n<meta property="og:image" content="${attr(s.image)}">\n<meta name="twitter:card" content="summary_large_image">\n<meta name="twitter:title" content="${attr(s.title)}">\n<meta name="twitter:description" content="${attr(s.desc)}">\n<meta name="twitter:image" content="${attr(s.image)}">\n<link rel="icon" href="${attr(s.icon)}">\n<link rel="apple-touch-icon" href="${attr(s.icon)}">\n`;
  if (s.brand) head += `<meta name="theme-color" content="${attr(s.brand)}">\n`;
  if (s.gsc) head += `<meta name="google-site-verification" content="${attr(s.gsc)}">\n`;
  if (s.ga) head += `<script async src="https://www.googletagmanager.com/gtag/js?id=${attr(s.ga)}"></script>\n<script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag('js',new Date());gtag('config','${attr(s.ga)}');</script>\n`;
  for (const o of s.jsonld || []) head += `<script type="application/ld+json">${j(o)}</script>\n`;
  if (s.css) head += `<style id="dyn">${s.css.replace(/</g, '')}</style>\n`;
  return tpl
    .replace(/<title>[^<]*<\/title>\s*/, '')
    .replace(/<meta name="description"[^>]*>\s*/, '')
    .replace(/<meta name="theme-color"[^>]*>\s*/, '')
    .replace(/<link rel="icon"[^>]*>\s*/, '')
    .replace('<!--HEAD-->', () => head)
    .replace('<!--SSR-->', () => `<div class="ssr">${s.body}</div>`);
}

/* ───────── التحقق من هوية تيليجرام (WebCrypto) ───────── */
async function hmacSign(keyBytes, dataBytes) {
  const k = await crypto.subtle.importKey('raw', keyBytes, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await crypto.subtle.sign('HMAC', k, dataBytes));
}

async function verifyInitData(raw, token) {
  const p = new URLSearchParams(raw);
  const hash = p.get('hash');
  if (!hash || !/^[0-9a-f]{64}$/.test(hash)) return null;
  p.delete('hash');
  const check = [...p.entries()].sort(([a], [b]) => (a < b ? -1 : 1)).map(([k, v]) => `${k}=${v}`).join('\n');
  const secret = await hmacSign(enc.encode('WebAppData'), enc.encode(token));
  const key = await crypto.subtle.importKey('raw', secret, { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']);
  const sig = Uint8Array.from(hash.match(/../g).map((h) => parseInt(h, 16)));
  if (!(await crypto.subtle.verify('HMAC', key, sig, enc.encode(check)))) return null; // مقارنة ثابتة الزمن
  if (now() - Number(p.get('auth_date')) > 86400) return null;
  try { return JSON.parse(p.get('user')); } catch { return null; }
}


